<div class="page-title"><div><em><?=date('l, F j')?></em><h1><?php $h=(int)date('G');echo $h<12?tl('dash_good_morning'):($h<18?tl('dash_good_afternoon'):tl('dash_good_evening'));?>, <?=html_escape($current_user['first_name'])?></h1><p><?=tl('dash_today')?></p></div><a class="btn" href="<?=site_url('transfer')?>">↗ <?=tl('dash_send_money')?></a></div>
<section class="balance"><div><span><?=tl('dash_total_balance')?></span><h2><?=money($total_balance)?><small> USD</small></h2><b>↗ Your complete financial position</b></div><?php if($accounts):$a=$accounts[0];?><div class="balance-account"><small><?=strtoupper(tl('dash_primary'))?> <?=strtoupper($a['type'])?></small><strong><?=html_escape($a['name'])?></strong><span>•••• <?=substr($a['account_number'],-4)?></span><h3><?=money($a['available_balance'])?></h3></div><?php endif?></section>
