<div class="grid two"><section class="panel"><div class="panel-head"><div><h2><?=tl('dash_recent_transactions')?></h2><p><?=tl('dash_latest_activity')?></p></div><a href="<?=site_url('transactions')?>"><?=tl('dash_view_all')?> ›</a></div><div class="transaction-list"><?php if(!$transactions):?><div class="bell-empty" style="padding:28px">No recent activity yet.</div><?php endif?><?php foreach($transactions as $t):?><div class="transaction"><i><?=transaction_icon($t['type'])?></i><div><b><?=html_escape($t['description'])?></b><small><?=html_escape($t['category'])?> · <?=date('M j',strtotime($t['transaction_date']))?></small></div><strong class="<?=$t['type']?>"><?=$t['type']==='credit'?'+':'−'?> <?=money($t['amount'])?></strong></div><?php endforeach?></div></section><section class="panel spending"><div class="panel-head"><div><h2><?=tl('dash_monthly_spending')?></h2><p><?=date('F')?> summary</p></div></div><?php $total_spend=array_sum(array_column($spending,'total'));$palette=array('navy','purple','green','gold');?><div class="donut"><span><b><?=money($total_spend)?></b><small><?=tl('dash_spent_this_month')?></small></span></div><ul><?php $i=0;foreach($spending as $s):?><li><i class="<?=$palette[$i%4]?>"></i><?=html_escape($s['category'])?> <b><?=money($s['total'])?></b></li><?php $i++;endforeach?><?php if(!$spending):?><li style="color:#718095">No spending recorded this month yet.</li><?php endif?></ul></section></div>
<div class="insight"><i>$</i><div><small><?=strtoupper(tl('dash_insight'))?></small><h3>You've spent <?=money($summary['expenses'])?> this month</h3><p><?=$summary['income']>0?'Your total income for '.date('F').' is '.money($summary['income']).'.':'Keep an eye on your monthly budget.'?></p></div><a href="<?=site_url('transactions')?>"><?=tl('dash_view_activity')?> ›</a></div>
<dialog id="dash-deposit-modal"><div class="dialog-head"><h2><?=tl('dash_deposit')?></h2><button data-close>×</button></div><?=form_open('accounts/deposit')?><label><?=tl('common_account')?></label><select name="account_id" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=html_escape($a['name'])?> •<?=substr($a['account_number'],-4)?> — <?=money($a['available_balance'],$a['currency'])?></option><?php endforeach?></select><label><?=tl('common_amount')?></label><input name="amount" type="number" step="0.01" min="0.01" required placeholder="0.00"><button class="btn wide"><?=tl('common_save')?></button></form></dialog><script>document.querySelector('[data-quick-deposit]')?.addEventListener('click',function(e){e.preventDefault();document.getElementById('dash-deposit-modal')?.showModal();});</script>